    if (kind === "comsat") idle9.headDeg = yaw + ((t * COMSAT_SWEEP9) % 360);
    /* 공사 발판의 경광등은 그 자체가 '대기'다(요청: "스캐폴드도 idle 상태에서 경광등 깜빡"). */
    if (kind === "scaffold") idle9.blink = blink9;
